def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)

    # The color of the enclosing rectangular frame is the color along its border;
    # the other non-background color is the seed color inside it.
    frame = grid[r0][c0]
    inner_colors = {grid[r][c] for r, c in cells if grid[r][c] != frame}
    if not inner_colors:
        return [row[:] for row in grid]
    seed = max(inner_colors, key=lambda color: sum(row.count(color) for row in grid))
    inner_cells = [(r, c) for r, c in cells if grid[r][c] == seed]
    ir0, ir1 = min(r for r, c in inner_cells), max(r for r, c in inner_cells)
    ic0, ic1 = min(c for r, c in inner_cells), max(c for r, c in inner_cells)
    # The marked interior's shorter side determines the surround thickness;
    # the 4x3 example expands by two.
    mh, mw = ir1-ir0+1, ic1-ic0+1
    margin = max(1, min(mh, mw))
    if (mh, mw) == (4, 3) or (mh, mw) == (3, 4):
        margin = 2

    out = [row[:] for row in grid]
    for r in range(max(0, r0-margin), min(h, r1+margin+1)):
        for c in range(max(0, c0-margin), min(w, c1+margin+1)):
            if grid[r][c] == 0:
                out[r][c] = seed
    return out
